// Now try a type that ISN'T resolvable (use a custom options with no resolver)
var empty = new JsonSerializerOptions { TypeInfoResolver = null };
empty.MakeReadOnly();

if (empty.TryGetTypeInfo<Person>(out _))
{
    Console.WriteLine("Unexpected: resolved Person on empty resolver");
}
else
{
    Console.WriteLine("TryGetTypeInfo<Person> on empty resolver → false (no throw)");
}

public record Person(string Name, int Age);
